//! Canonical time name reflection retains actual DOMString attributes.
use super::*;
fn fixture()->(Document,Forms,Page){let mut d=crate::html::parse("<html><body><map id=map name=2026-11-24>Fallback map</map><input id=neighbor value=seed></body></html>");d.scripting_enabled=true;let mut f=Forms::new(&d);let mut p=Page::new();let location=crate::navigation::address("https://map-name.test/source",&crate::navigation::Location::home()).unwrap();p.set_location(&location);p.set_resource_base(&location);assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);(d,f,p)}
fn run(d:&mut Document,f:&mut Forms,p:&mut Page,s:&str){p.runtime.execute(s,&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap();}
#[test]
fn map_name_canonical_interface_descriptors_and_initial_attribute(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('map'),C=HTMLMapElement,P=C.prototype,a=Object.getOwnPropertyDescriptor(P,'name');if(!(x instanceof C)||Object.getPrototypeOf(x)!==P||!a||!a.enumerable||!a.configurable||a.get.length!==0||a.set.length!==1||a.get.name!=='get name'||a.set.name!=='set name'||Object.hasOwn(x,'name')||x.name!=='2026-11-24'||x.textContent!=='Fallback map')throw 'canonical time metadata';var caught=false;try{new C();}catch(e){caught=e instanceof TypeError;}if(!caught)throw 'illegal time construction';"#);}
#[test]
fn map_name_exact_native_setter_aliases_and_observer_records(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('map'),a=x.getAttributeNode('name'),watch=new MutationObserver(function(){});watch.observe(x,{attributes:true,attributeOldValue:true});x.name='A\ud800Z';var records=watch.takeRecords();if(x.name!=='A\ud800Z'||a.value!==x.name||x.getAttributeNode('name')!==a||records.length!==1||records[0].attributeName!=='name'||records[0].oldValue!=='2026-11-24'||x.textContent!=='Fallback map')throw 'exact time setter';a.nodeValue='not a date';if(x.name!=='not a date'||a.value!=='not a date')throw 'time is plain reflection';x.removeAttribute('name');if(x.name!==''||a.ownerElement!==null||a.value!=='not a date')throw 'removed name default';"#);}
#[test]
fn map_name_inert_namespace_conversion_and_clone_import_authority(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var doc=new Document(),x=doc.createElementNS('http://www.w3.org/1999/xhtml','t:map');if(!(x instanceof HTMLMapElement)||x.name!=='')throw 'inert time defaults';var calls=0;x.name={toString:function(){calls++;x.setAttribute('name','author');return 'R\udfffZ';}};if(calls!==1||x.name!=='R\udfffZ'||x.getAttribute('name')!==x.name)throw 'once exact conversion';x.setAttributeNS('urn:foreign','name','foreign');x.setAttributeNS(null,'NAME','upper');if(x.name!=='R\udfffZ')throw 'null namespace exact local name';var clone=x.cloneNode(false);if(clone.name!==x.name)throw 'namespace clone';x.removeAttributeNS('urn:foreign','name');x.removeAttributeNS(null,'NAME');var copy=document.importNode(x,false);if(clone.name!==x.name||copy.name!==x.name||copy.ownerDocument!==document||clone.getAttributeNode('name')===x.getAttributeNode('name'))throw 'actual time clone/import';clone.name='independent';if(x.name!=='R\udfffZ'||copy.name!=='R\udfffZ')throw 'independent copied metadata';"#);}

// Exact name metadata preserves conversion, concrete brands and native authority.
#[test]
fn map_name_conversion_reentry_abrupt_symbol_and_current_attr_identity(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('map'),old=x.getAttributeNode('name'),watch=new MutationObserver(function(){});watch.observe(x,{attributes:true,attributeOldValue:true});var calls=0;x.name={toString:function(){calls++;x.removeAttribute('name');x.setAttribute('name','replacement');return 'A\ud800Z';}};var current=x.getAttributeNode('name'),records=watch.takeRecords();if(calls!==1||current===old||old.ownerElement!==null||old.value!=='2026-11-24'||current.value!=='A\ud800Z'||records.length!==3||records[2].oldValue!=='replacement')throw 'current real Attr after conversion';var marker={},caught;try{x.name={toString:function(){x.setAttribute('name','author effect');throw marker;}};}catch(e){caught=e;}records=watch.takeRecords();if(caught!==marker||x.name!=='author effect'||records.length!==1||records[0].oldValue!=='A\ud800Z')throw 'abrupt conversion preserves author effect';caught=false;try{x.name=Symbol('map');}catch(e){caught=e instanceof TypeError;}if(!caught||watch.takeRecords().length||x.name!=='author effect')throw 'Symbol conversion refusal';for(var value of [null,undefined,0,false]){x.name=value;if(x.name!==String(value))throw 'ordinary DOMString conversion';}if(x.textContent!=='Fallback map')throw 'metadata leaves displayed text';"#);
}
#[test]
fn map_name_descriptors_brands_author_override_and_saved_constructor(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('map'),C=HTMLMapElement,P=C.prototype,a=Object.getOwnPropertyDescriptor(P,'name'),calls=0;for(var bad of [{},Object.create(P),document.body,document.createElementNS('urn:foreign','map'),new Document().createElementNS('http://www.w3.org/1999/xhtml','MAP')]){var caught=false;try{a.get.call(bad);}catch(e){caught=e instanceof TypeError;}if(!caught)throw 'getter concrete brand';caught=false;try{a.set.call(bad,{toString:function(){calls++;return 'bad';}});}catch(e){caught=e instanceof TypeError;}if(!caught||calls)throw 'brand before conversion';}Object.defineProperty(x,'name',{value:'author',writable:true,configurable:true});if(x.name!=='author'||a.get.call(x)!=='2026-11-24')throw 'canonical authority';a.set.call(x,'canonical');if(x.name!=='author'||x.getAttribute('name')!=='canonical')throw 'borrowed real setter';delete x.name;if(x.name!=='canonical'||Object.hasOwn(x,'name'))throw 'restored inherited reflection';delete window.HTMLMapElement;if(!(x instanceof C)||Object.getPrototypeOf(x)!==P)throw 'saved original interface';"#);
}
#[test]
fn map_name_native_inert_attribute_aliases_namespace_and_exact_copies(){
 for inert in [false,true]{let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,if inert{"var x=new Document().createElementNS('http://www.w3.org/1999/xhtml','map');x.setAttribute('name','2026-11-24');"}else{"var x=document.getElementById('map');"});run(&mut d,&mut f,&mut p,r#"var a=x.getAttributeNode('name');for(var writer of ['value','nodeValue','textContent']){a[writer]='R\ud800'+writer;if(x.name!=='R\ud800'+writer||x.getAttributeNode('name')!==a)throw 'exact attached alias';}x.setAttributeNS('urn:foreign','name','foreign');x.setAttributeNS(null,'NAME','upper');if(x.name!=='R\ud800textContent'||x.getAttributeNodeNS(null,'name')!==a)throw 'exact null namespace/local name';x.setAttributeNS(null,'name','no date parsing');if(x.name!=='no date parsing'||a.value!==x.name)throw 'exact null namespace writer';var copy=x.cloneNode(false);if(copy.name!==x.name||copy.getAttributeNode('name')===a)throw 'independent clone';x.removeAttributeNS(null,'name');if(x.name!==''||a.ownerElement!==null||copy.name!=='no date parsing')throw 'removed actual default';"#);}
}
#[test]
fn map_name_native_adoption_and_return_keep_actual_interface_attr_and_child_handles(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('map'),attr=x.getAttributeNode('name'),first=x.firstChild,list=x.childNodes,C=HTMLMapElement,doc=new Document();if(doc.adoptNode(x)!==x||x.ownerDocument!==doc||x.parentNode!==null||!(x instanceof C)||x.name!=='2026-11-24'||attr.ownerElement!==x||attr.ownerDocument!==doc||x.firstChild!==first||x.childNodes!==list)throw 'actual native time adoption';x.name='A\udfffZ';if(document.adoptNode(x)!==x||x.ownerDocument!==document||x.name!=='A\udfffZ'||x.getAttributeNode('name')!==attr)throw 'same native identity return';document.body.appendChild(x);if(x.firstChild!==first||x.childNodes!==list||x.textContent!=='Fallback map'||attr.value!==x.name)throw 'reconnected time source';"#);
}
#[test]
fn map_name_saved_child_origin_precedes_conversion_and_recovers(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('map'),frame=document.createElement('iframe');frame.hidden=true;document.body.appendChild(frame);var C=frame.contentWindow.HTMLMapElement,a=Object.getOwnPropertyDescriptor(C.prototype,'name'),calls=0;if(C===HTMLMapElement||a.get.call(x)!=='2026-11-24')throw 'captured time accessor';"#);p.set_location(&crate::navigation::address("https://other-time.test/",&crate::navigation::Location::home()).unwrap());let before=format!("{:?}",d.nodes);let commits=p.state.dom_commits;for source in ["a.get.call(x);","a.set.call(x,{toString:function(){calls++;return 'bad';}});"]{p.begin_job();let e=p.runtime.execute(source,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(e.contains("origin")||e.contains("Security"),"{e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!(p.state.dom_commits,commits);}p.set_location(&crate::navigation::address("https://map-name.test/source",&crate::navigation::Location::home()).unwrap());p.begin_job();run(&mut d,&mut f,&mut p,"if(calls)throw 'origin precedes conversion';a.set.call(x,'recovered');if(a.get.call(x)!=='recovered')throw 'time origin recovery';");
}

// Shared reflection transactions must refuse before observable changes.
#[test]
fn map_name_writer_refusal_preserves_native_and_inert_records_and_recovers(){
 for inert in [false,true]{for source in [r"x.name='Long canonical \ud800 DateTime replacement';",r"x.setAttribute('name','Long canonical \ud800 DateTime replacement');",r"attr.value='Long canonical \ud800 DateTime replacement';",r"attr.nodeValue='Long canonical \ud800 DateTime replacement';",r"attr.textContent='Long canonical \ud800 DateTime replacement';"]{for mode in 0..5{
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,if inert{"var x=new Document().createElementNS('http://www.w3.org/1999/xhtml','map');x.setAttribute('name','2026-11-24');"}else{"var x=document.getElementById('map');"});run(&mut d,&mut f,&mut p,"var attr=x.getAttributeNode('name'),watch=new MutationObserver(function(){});watch.observe(x,{attributes:true,attributeOldValue:true});");p.state.rebuild(&d).unwrap();let before=format!("{:?}",d.nodes);let state=(p.state.retained,p.state.dom_commits,p.state.attributes.len(),p.state.detached_nodes.clone());let controls=f.controls.iter().map(|(n,c)|(*n,c.owner,c.value.text(),c.disabled,c.checked)).collect::<Vec<_>>();let limit=p.state.retained_limit;let strings=p.state.limits.host.string_bytes;p.begin_job();match mode{0=>p.state.host_work=0,1=>p.state.copy_work=0,2=>p.state.retained_limit=p.state.retained,3=>p.state.limits.host.string_bytes=1,_=>p.state.execution_deadline=Some(Instant::now())};let e=p.runtime.execute(source,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).expect_err(&format!("name writer {inert}/{source}/{mode}"));assert!(e.contains("work")||e.contains("allowance")||e.contains("limit")||e.contains("bound"),"{inert}/{mode}: {e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.retained,p.state.dom_commits,p.state.attributes.len(),p.state.detached_nodes.clone()),state);assert_eq!(f.controls.iter().map(|(n,c)|(*n,c.owner,c.value.text(),c.disabled,c.checked)).collect::<Vec<_>>(),controls);p.state.retained_limit=limit;p.state.limits.host.string_bytes=strings;p.state.execution_deadline=None;p.begin_job();run(&mut d,&mut f,&mut p,"if(attr.value!=='2026-11-24'||x.name!=='2026-11-24'||watch.takeRecords().length)throw 'atomic name writer refusal';");run(&mut d,&mut f,&mut p,source);run(&mut d,&mut f,&mut p,r"var records=watch.takeRecords();if(x.name!=='Long canonical \ud800 DateTime replacement'||records.length!==1||records[0].oldValue!=='2026-11-24'||records[0].attributeName!=='name'||x.getAttributeNode('name')!==attr)throw 'fresh name writer recovery';");
 }}}
}
#[test]
fn map_name_reads_enforce_work_copy_string_and_deadline_without_retained_growth(){
 for inert in [false,true]{for mode in 0..5{let(mut d,mut f,mut p)=fixture();let object=if inert{run(&mut d,&mut f,&mut p,r"var time=new Document().createElementNS('http://www.w3.org/1999/xhtml','map');time.name='A\ud800Z';");let Value::Host(object)=p.runtime.execute("time;",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap()else{panic!("inert time handle")};object}else{run(&mut d,&mut f,&mut p,r"document.getElementById('map').name='A\ud800Z';");node_handle((0..d.nodes.len()).find(|&n|d.attr(n,"id")==Some("map")).unwrap())};let before=format!("{:?}",d.nodes);let state=(p.state.retained,p.state.dom_commits,p.state.attributes.len());let limit=p.state.retained_limit;let strings=p.state.limits.host.string_bytes;p.begin_job();match mode{0=>p.state.host_work=0,1=>p.state.copy_work=0,2=>p.state.limits.host.string_bytes=1,3=>p.state.execution_deadline=Some(Instant::now()),_=>p.state.retained_limit=p.state.retained};let result=Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}.map_name_get(object);if mode==4{assert!(result.is_ok());}else{let e=result.unwrap_err();assert!(e.contains("work")||e.contains("allowance")||e.contains("time")||e.contains("bound"),"{e}");}assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.retained,p.state.dom_commits,p.state.attributes.len()),state);p.state.execution_deadline=None;p.state.retained_limit=limit;p.state.limits.host.string_bytes=strings;p.begin_job();assert!(Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}.map_name_get(object).is_ok());}}
}

#[test]
fn map_name_collection_item_keeps_ordinary_method_descriptor_and_concrete_brand(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var P=HTMLCollection.prototype,a=Object.getOwnPropertyDescriptor(P,'item'),method=a.value,list=document.body.children;if(typeof method!=='function'||a.get!==undefined||!a.enumerable||!a.writable||!a.configurable||method.name!=='item'||method.length!==1||list.item!==method||method.call(list,0)!==document.getElementById('map')||method.call(list,99)!==null)throw 'ordinary collection item';var caught=false;try{method.call({length:1,0:document.body},0);}catch(e){caught=e instanceof TypeError;}if(!caught)throw 'item concrete collection';caught=false;try{new method();}catch(e){caught=e instanceof TypeError;}if(!caught)throw 'item illegal construction';Object.freeze(P);a=Object.getOwnPropertyDescriptor(P,'item');if(a.value!==method||a.writable||a.configurable||!a.enumerable||list.item!==method)throw 'frozen item identity';"#);
}
#[test]
fn map_name_foreign_import_and_neighbor_raw_attribute_guards_remain_atomic(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var source=new Document().createElementNS('http://www.w3.org/1999/xhtml','map');source.name='actual';source.setAttributeNS('urn:foreign','name','foreign');var neighbor=document.getElementById('neighbor');");for code in ["document.importNode(source,false);",r"neighbor.setAttribute('name','A\ud800Z');"]{let before=format!("{:?}",d.nodes);let state=(p.state.retained,p.state.dom_commits,p.state.attributes.len(),p.state.detached_nodes.clone());p.begin_job();let e=p.runtime.execute(code,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(e.contains("unsupported namespaced")||e.contains("Unpaired attribute"),"{e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.retained,p.state.dom_commits,p.state.attributes.len(),p.state.detached_nodes.clone()),state);p.begin_job();run(&mut d,&mut f,&mut p,"if(source.name!=='actual'||source.getAttributeNS('urn:foreign','name')!=='foreign'||neighbor.value!=='seed'||neighbor.hasAttribute('name'))throw 'preserved attribute guards';");}
}

#[test]
fn map_name_collection_lookup_reads_actual_exact_records(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('map'),list=document.getElementsByTagName('map');x.name='A\ud800Z';if(list.namedItem('A\ud800Z')!==x||list.namedItem('A\ufffdZ')!==null)throw 'exact map named lookup';var a=x.getAttributeNode('name');a.nodeValue='replacement';if(list.namedItem('replacement')!==x||list.namedItem('A\ud800Z')!==null||x.name!=='replacement')throw 'live native map name';x.removeAttribute('name');if(x.name!==''||list.namedItem('replacement')!==null)throw 'removed actual map name';"#);
}
#[test]
fn map_name_accessor_rejects_other_named_native_interfaces_before_conversion(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var a=Object.getOwnPropertyDescriptor(HTMLMapElement.prototype,'name'),calls=0;for(var x of [document.getElementById('neighbor'),document.createElement('form'),document.createElement('output')]){var caught=false;try{a.get.call(x);}catch(e){caught=e instanceof TypeError;}if(!caught)throw 'Map getter real brand';caught=false;try{a.set.call(x,{toString:function(){calls++;return 'bad';}});}catch(e){caught=e instanceof TypeError;}if(!caught||calls||x.hasAttribute('name'))throw 'Map brand before author conversion';}"#);
}

#[test]
fn map_name_clone_method_keeps_ordinary_descriptor_deletion_freeze_and_saved_identity(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var P=Node.prototype,a=Object.getOwnPropertyDescriptor(P,'cloneNode'),method=a.value,x=document.getElementById('map');if(typeof method!=='function'||a.get!==undefined||!a.enumerable||!a.writable||!a.configurable||method.name!=='cloneNode'||method.length!==0||x.cloneNode!==method)throw 'ordinary clone descriptor';var caught=false;try{method.call({});}catch(e){caught=e instanceof TypeError;}if(!caught)throw 'clone concrete receiver';delete P.cloneNode;if(x.cloneNode!==undefined)throw 'deleted clone method must not resurrect';var copy=method.call(x,true);if(copy.name!==x.name||copy.ownerDocument!==document||copy.firstChild===x.firstChild||copy.textContent!==x.textContent||!(copy instanceof HTMLMapElement))throw 'saved genuine clone method';Object.defineProperty(P,'cloneNode',a);Object.freeze(P);a=Object.getOwnPropertyDescriptor(P,'cloneNode');if(a.value!==method||a.writable||a.configurable||!a.enumerable||x.cloneNode!==method)throw 'frozen ordinary clone identity';"#);
}
